function escapeHtmlRoster(s){
  return String(s??'')
    .replace(/&/g,'&amp;')
    .replace(/</g,'&lt;')
    .replace(/>/g,'&gt;')
    .replace(/"/g,'&quot;');
}
function rosterAbilityBlurb(t, abId){
  const id=abId||(t&&t.id)||'';
  const ab={id, level:1};
  const packRow=typeof packRowForAbility==='function'?packRowForAbility(ab):null;
  if(typeof formatAbilityBlurbHtml==='function'){
    const html=formatAbilityBlurbHtml(ab, t, packRow);
    if(html) return html;
  }
  const raw=(t&&t.levels&&t.levels[0]&&t.levels[0].desc!=null)?t.levels[0].desc:(t&&t.desc!=null?t.desc:'No description');
  const text=typeof globalThis.normalizeCombatEnLabel==='function'?globalThis.normalizeCombatEnLabel(String(raw).trim()):String(raw).trim();
  return escapeHtmlRoster(text);
}
function abilityBlurbForTemplate(tmpl, abId){
  const id=abId||(tmpl&&tmpl.id)||'';
  const ab={id, level:1};
  const packRow=typeof packRowForAbility==='function'?packRowForAbility(ab):null;
  if(typeof formatAbilityBlurbHtml==='function'){
    const html=formatAbilityBlurbHtml(ab, tmpl, packRow);
    if(html) return html;
  }
  return escapeHtmlRoster(String(tmpl?.levels?.[0]?.desc||tmpl?.desc||'No description available.'));
}
/** Same skill slot → ability pipeline as a new run (family evolution + ABILITY_TEMPLATES), for roster UI only. */
function buildRosterPreviewStubForBirdKey(birdKey){
  const bd=BIRDS[birdKey];
  if(!bd) return null;
  return{
    birdKey,
    name: bd.name,
    portraitKey: bd.portraitKey||birdKey,
    size: bd.size||'medium',
    class: bd.class,
    stats: {...bd.stats},
    abilities: (bd.startAbilities||[]).map(id=>({id, level:1})),
    energyBonus: 0,
    firstAttackFree: false,
    firstSpellFree: false,
    augFirstSpellCostDown: 0,
    familyEvolutionState: null,
  };
}
function rosterPreviewSlotTag(birdKey, stub, ab, idx){
  if(!stub||!usesFamilySkillEvolution(stub)) return ['CORE','LINE 2','LINE 3','LINE 4'][idx]||'SKILL';
  const slots=getSkillSlots(stub).slice().sort((a,b)=>(a.slotIndex||0)-(b.slotIndex||0));
  const slot=slots.find(s=>Number.isFinite(ab?.slotIndex)&&s.slotIndex===ab.slotIndex)||slots[idx];
  const fam=slot?getSkillSlotFamilyDef(slot, birdKey):null;
  if(fam?.displayName) return String(fam.displayName).toUpperCase();
  return ['CORE','LINE 2','LINE 3','LINE 4'][idx]||'SKILL';
}
function materializeRosterPreviewKit(birdKey){
  const out={abilities:[], energyMax:0, stats:null, slotTags:[]};
  const stub=buildRosterPreviewStubForBirdKey(birdKey);
  if(!stub) return out;
  const prev=G.player;
  try{
    G.player=stub;
    stub.energyMax=computePlayerMaxEnergy();
    // Resolve the card tier first so slot seeding unlocks the right number of
    // abilities (green => 3, blue => 4) in the character-select preview.
    if(typeof applyBirdCardProgression==='function') applyBirdCardProgression(stub);
    applyPlayerSkillsFromCardTier(stub);
    syncPlayerAbilitiesFromSkillSlots(stub);
    out.abilities=Array.isArray(stub.abilities)?stub.abilities.slice():[];
    out.energyMax=Math.max(0, Number(stub.energyMax)||computePlayerMaxEnergy());
    out.stats=stub.stats?{...stub.stats}:{};
    out.slotTags=out.abilities.map((ab, i)=>rosterPreviewSlotTag(birdKey, stub, ab, i));
  }finally{
    G.player=prev;
  }
  return out;
}

let BIRD_UPGRADE_PREVIEW_KEY=null;
let BIRD_UPGRADE_PREVIEW_MODEL=null;

function materializeRosterPreviewKitForCardProgress(birdKey, tier, stars){
  const out={energyMax:0, stats:null, abilities:[], slotTags:[]};
  const stub=buildRosterPreviewStubForBirdKey(birdKey);
  if(!stub) return out;
  const prev=G.player;
  try{
    G.player=stub;
    stub.energyMax=computePlayerMaxEnergy();
    stub._birdCardTier=tier;
    stub._birdCardStars=stars;
    if(typeof applyBirdCardStats==='function') applyBirdCardStats(stub, tier, stars);
    applyPlayerSkillsFromCardTier(stub, tier, stars);
    syncPlayerAbilitiesFromSkillSlots(stub);
    out.abilities=Array.isArray(stub.abilities)?stub.abilities.slice():[];
    out.slotTags=out.abilities.map((ab, i)=>rosterPreviewSlotTag(birdKey, stub, ab, i));
    out.energyMax=Math.max(0, Number(stub.energyMax)||computePlayerMaxEnergy());
    out.stats=stub.stats?{...stub.stats}:{};
  }finally{
    G.player=prev;
  }
  return out;
}

function birdUpgradeTierMeta(tier){
  const pack=Avian?.data?.birdCardTiers;
  return{
    label:pack?.TIER_LABELS?.[tier]||tier,
    css:pack?.TIER_CSS?.[tier]||'tier-grey',
  };
}

function birdUpgradeStarsHtml(stars){
  const pack=Avian?.data?.birdCardTiers;
  return renderBirdCardStarsHtml(stars, pack?.STARS_PER_TIER||5);
}

function buildBirdUpgradePreviewModel(birdKey){
  const bird=BIRDS?.[birdKey];
  if(!bird) return null;
  const progress=typeof getBirdCardProgress==='function'?getBirdCardProgress(birdKey):null;
  const ownsCard=typeof ownsBirdCard==='function'?ownsBirdCard(birdKey):true;
  const feathers=typeof getSpeciesFeathers==='function'?getSpeciesFeathers(birdKey):0;
  const cost=progress?.cost??0;
  const preview=progress?.preview||null;
  const canConfirm=!!(ownsCard&&progress?.canUpgrade&&preview&&feathers>=cost);
  const tierBefore=progress?.tier||(typeof getBirdCardTier==='function'?getBirdCardTier(birdKey):'grey');
  const starsBefore=progress?.stars??(typeof getBirdCardStars==='function'?getBirdCardStars(birdKey):0);
  const tierAfter=preview?.tierAfter||tierBefore;
  const starsAfter=preview?.starsAfter??starsBefore;
  const currentKit=materializeRosterPreviewKitForCardProgress(birdKey, tierBefore, starsBefore);
  const upgradedKit=materializeRosterPreviewKitForCardProgress(birdKey, tierAfter, starsAfter);
  const abilitiesBefore=currentKit.abilities||[];
  const abilitiesAfter=upgradedKit.abilities||[];
  const abilitiesChanged=abilitiesBefore.length!==abilitiesAfter.length
    ||abilitiesBefore.some((ab, i)=>String(ab?.id||'')!==String(abilitiesAfter[i]?.id||''));
  const passiveInfo=getBirdPassiveInfo(birdKey);
  const passiveName=passiveInfo?.name||bird.passive?.name||'Passive';
  const passiveText=passiveInfo?.desc||passiveInfo?.effect||bird.passive?.desc||'';
  const growthPack=Avian?.data?.featherGrowthProfiles;
  const growthProfile=typeof growthPack?.getGrowthProfileForBird==='function'?growthPack.getGrowthProfileForBird(birdKey):null;
  const statKeys=[
    ['hp','HP'],
    ['atk','ATK'],
    ['def','DEF'],
    ['spd','SPD'],
    ['acc','ACC'],
    ['dodge','DODGE'],
    ['matk','MATK'],
    ['mdef','MDEF'],
  ];
  return{
    birdKey,
    name:bird.name||birdKey,
    sizeClass:getUISizeClass(bird, 'select'),
    feathers,
    cost,
    canConfirm,
    reason:!ownsCard?'no_card':!progress?.canUpgrade?'max_tier':feathers<cost?'feathers':'',
    tierBefore,
    starsBefore,
    tierAfter,
    starsAfter,
    tierBeforeMeta:birdUpgradeTierMeta(tierBefore),
    tierAfterMeta:birdUpgradeTierMeta(tierAfter),
    isTierUp:!!preview?.isTierUp,
    statsBefore:currentKit.stats||{},
    statsAfter:upgradedKit.stats||{},
    passiveName,
    passiveBefore:passiveText,
    passiveAfter:passiveText,
    passiveChanged:false,
    abilitiesBefore,
    abilitiesAfter,
    abilitiesChanged,
    statRows:statKeys
      .filter(([key])=>currentKit.stats?.[key]!=null||upgradedKit.stats?.[key]!=null)
      .map(([key,label])=>{
        const before=Number(currentKit.stats?.[key]??0);
        const after=Number(upgradedKit.stats?.[key]??0);
        const lookupKey=key==='hp'?'maxHp':key;
        const growthLabel=typeof growthPack?.getGrowthTierLabelForStat==='function'&&growthProfile
          ? growthPack.getGrowthTierLabelForStat(lookupKey, growthProfile)
          : '';
        return{key,label,before,after,delta:after-before,growthLabel};
      }),
  };
}

function birdUpgradeReasonText(model){
  if(!model) return 'Upgrade preview unavailable.';
  if(model.reason==='no_card') return 'Hatch this bird card before upgrading.';
  if(model.reason==='max_tier') return 'This bird card is already at maximum tier and stars.';
  if(model.reason==='feathers') return `Need ${model.cost} Species Feathers; you have ${model.feathers}.`;
  return '';
}

function formatBirdUpgradeStatValue(value){
  const n=Number(value);
  if(!Number.isFinite(n)) return '0.00';
  return n.toFixed(2);
}

function birdUpgradeStatRowsHtml(model){
  return model.statRows.map(row=>{
    const deltaClass=row.delta>0?' is-positive':row.delta<0?' is-negative':'';
    const deltaText=row.delta>0?`+${formatBirdUpgradeStatValue(row.delta)}`:formatBirdUpgradeStatValue(row.delta);
    const growthNote=row.growthLabel?`<small class="bird-upgrade-growth-tag">${escapeHtmlRoster(row.growthLabel)}</small>`:'';
    return `<div class="bird-upgrade-stat-row"><span>${escapeHtmlRoster(row.label)}${growthNote}</span><strong>${escapeHtmlRoster(formatBirdUpgradeStatValue(row.before))}</strong><i aria-hidden="true">→</i><strong>${escapeHtmlRoster(formatBirdUpgradeStatValue(row.after))}</strong><em class="${deltaClass}">${escapeHtmlRoster(deltaText)}</em></div>`;
  }).join('');
}

function birdUpgradeAbilityLabel(ab){
  const id=typeof ab==='string'?ab:(ab&&ab.id);
  const t=getAbilityTemplateForUI(ab)||getAbilityTemplateForUI({id,level:1})||{};
  return t.name||id||'Skill';
}

function birdUpgradeAbilitiesHtml(model){
  if(!model.abilitiesChanged) return '';
  const before=model.abilitiesBefore||[];
  const after=model.abilitiesAfter||[];
  if(!before.length&&!after.length) return '';
  const maxLen=Math.max(before.length, after.length);
  let rows='';
  for(let i=0;i<maxLen;i++){
    const b=before[i];
    const a=after[i];
    const bName=b?birdUpgradeAbilityLabel(b):'—';
    const aName=a?birdUpgradeAbilityLabel(a):'—';
    const changed=String(b?.id||'')!==String(a?.id||'');
    rows+=`<div class="bird-upgrade-stat-row${changed?' is-changed':''}"><span>Slot ${i+1}</span><strong>${escapeHtmlRoster(bName)}</strong><i aria-hidden="true">→</i><strong>${escapeHtmlRoster(aName)}</strong></div>`;
  }
  return `<div class="bird-upgrade-abilities is-changed"><h4>Starting skills</h4><div class="bird-upgrade-stat-head"><span>Slot</span><strong>Current</strong><i aria-hidden="true">→</i><strong>Upgraded</strong><em></em></div>${rows}</div>`;
}

function renderBirdUpgradePreviewModal(model, state='preview'){
  const modal=document.getElementById('bird-upgrade-modal');
  const content=document.getElementById('bird-upgrade-content');
  const title=document.getElementById('bird-upgrade-title');
  const confirm=document.getElementById('bird-upgrade-confirm');
  const cancel=document.getElementById('bird-upgrade-cancel');
  if(!modal||!content||!model) return;
  const isResult=state==='result';
  const reason=birdUpgradeReasonText(model);
  const resultBanner=isResult
    ? `<div class="bird-upgrade-result-banner">${model.isTierUp?'Tier advanced — new ability may unlock.':'Upgrade complete.'}</div>`
    : (model.upgradeBanner ? `<div class="bird-upgrade-result-banner">${escapeHtmlRoster(model.upgradeBanner)}</div>` : '');
  content.innerHTML=`
    ${resultBanner}
    <div class="bird-upgrade-summary">
      <div class="bird-upgrade-portrait" aria-hidden="true">${renderBirdIconHTML(model.birdKey, model.sizeClass, false)}</div>
      <div class="bird-upgrade-summary-body">
        <h3>${escapeHtmlRoster(model.name)}</h3>
        <div class="bird-upgrade-tier-line">
          <span class="bird-card-tier-badge ${model.tierBeforeMeta.css}">${escapeHtmlRoster(model.tierBeforeMeta.label)}</span>
          <span class="inventory-feather-stars">${birdUpgradeStarsHtml(model.starsBefore)}</span>
          <span class="bird-upgrade-arrow" aria-hidden="true">→</span>
          <span class="bird-card-tier-badge ${model.tierAfterMeta.css}">${escapeHtmlRoster(model.tierAfterMeta.label)}</span>
          <span class="inventory-feather-stars">${birdUpgradeStarsHtml(model.starsAfter)}</span>
        </div>
        <p class="bird-upgrade-cost">Cost: <strong>${escapeHtmlRoster(model.cost)}</strong> Species Feathers · Owned: <strong>${escapeHtmlRoster(model.feathers)}</strong></p>
      </div>
    </div>
    <div class="bird-upgrade-stats">
      <div class="bird-upgrade-stat-head"><span>Stat</span><strong>Current</strong><i aria-hidden="true">→</i><strong>Upgraded</strong><em>Change</em></div>
      ${birdUpgradeStatRowsHtml(model)}
    </div>
    <div class="bird-upgrade-passive">
      <h4>${escapeHtmlRoster(model.passiveName)}</h4>
      <p>${escapeHtmlRoster(model.passiveBefore||'No passive listed.')}</p>
      <p class="bird-upgrade-passive-note">Passives and class perks do not change with stars or tiers.</p>
    </div>
    ${birdUpgradeAbilitiesHtml(model)}
    ${reason?`<p class="bird-upgrade-warning">${escapeHtmlRoster(reason)}</p>`:''}`;
  if(title) title.textContent=isResult?'Upgrade Complete':'Upgrade Bird';
  if(confirm){
    confirm.hidden=isResult;
    confirm.disabled=!model.canConfirm||isResult;
    confirm.textContent=model.isTierUp?'Confirm tier upgrade':'Confirm upgrade';
  }
  if(cancel) cancel.textContent=isResult?'Done':'Cancel';
  modal.hidden=false;
  modal.setAttribute('aria-hidden','false');
  modal.classList.add('is-open');
  modal.classList.toggle('is-result', isResult);
}

function openBirdUpgradePreview(birdKey){
  const model=buildBirdUpgradePreviewModel(birdKey);
  if(!model){ try{ logMsg('Upgrade preview unavailable.','miss'); }catch(_){} return; }
  BIRD_UPGRADE_PREVIEW_KEY=birdKey;
  BIRD_UPGRADE_PREVIEW_MODEL=model;
  renderBirdUpgradePreviewModal(model, 'preview');
}

function closeBirdUpgradePreview(){
  const modal=document.getElementById('bird-upgrade-modal');
  if(modal){
    modal.hidden=true;
    modal.setAttribute('aria-hidden','true');
    modal.classList.remove('is-open','is-result');
  }
  BIRD_UPGRADE_PREVIEW_KEY=null;
  BIRD_UPGRADE_PREVIEW_MODEL=null;
}

function confirmBirdUpgradePreview(){
  const before=BIRD_UPGRADE_PREVIEW_MODEL||buildBirdUpgradePreviewModel(BIRD_UPGRADE_PREVIEW_KEY);
  if(!before||!before.canConfirm){
    try{ logMsg(birdUpgradeReasonText(before),'miss'); }catch(_){}
    if(before) renderBirdUpgradePreviewModal(before, 'preview');
    return;
  }
  if(typeof mutateBirdCard!=='function') return;
  const result=mutateBirdCard(before.birdKey);
  if(!result?.ok){
    try{ logMsg(result?.reason==='feathers'?'Not enough Species Feathers.':'Upgrade failed.','miss'); }catch(_){}
    const fresh=buildBirdUpgradePreviewModel(before.birdKey);
    BIRD_UPGRADE_PREVIEW_MODEL=fresh;
    if(fresh) renderBirdUpgradePreviewModal(fresh, 'preview');
    return;
  }
  if(typeof updateAscentPanel==='function') updateAscentPanel(before.birdKey);
  if(typeof buildBirdGrid==='function') try{ buildBirdGrid(); }catch(_){}
  if(typeof renderFortuneInventory==='function') try{ renderFortuneInventory(); }catch(_){}
  if(G.player?.birdKey===before.birdKey){
    if(typeof applyBirdCardProgression==='function') applyBirdCardProgression(G.player);
    if(typeof Avian?.mutations?.reapplyPlayerStatsFromSources==='function') Avian.mutations.reapplyPlayerStatsFromSources(G.player);
    ensureFamilyEvolutionState(G.player);
    applyPlayerSkillsFromCardTier(G.player);
    syncPlayerAbilitiesFromSkillSlots(G.player);
    if(G.phase==='PLAYER'||G.phase==='ENEMY'){
      if(typeof renderActions==='function') renderActions();
      if(typeof refreshBattleUI==='function') refreshBattleUI();
    }
  }
  const fresh=buildBirdUpgradePreviewModel(before.birdKey);
  if(fresh?.canConfirm){
    const tierMeta=birdUpgradeTierMeta(fresh.tierBefore);
    fresh.upgradeBanner=`Upgraded to ${tierMeta.label} · ${fresh.starsBefore} star${fresh.starsBefore===1?'':'s'}. Confirm again to keep upgrading.`;
    BIRD_UPGRADE_PREVIEW_MODEL=fresh;
    renderBirdUpgradePreviewModal(fresh, 'preview');
    try{ logMsg(`${before.name} upgraded.`, result.isTierUp?'hit':'good'); }catch(_){}
    return;
  }
  const resultModel={...before, feathers:Math.max(0, before.feathers-before.cost), canConfirm:false};
  BIRD_UPGRADE_PREVIEW_MODEL=resultModel;
  renderBirdUpgradePreviewModal(resultModel, 'result');
  try{ logMsg(`${before.name} upgraded.`, result.isTierUp?'hit':'good'); }catch(_){}
}

globalThis.buildBirdUpgradePreviewModel=buildBirdUpgradePreviewModel;
globalThis.openBirdUpgradePreview=openBirdUpgradePreview;
globalThis.closeBirdUpgradePreview=closeBirdUpgradePreview;
globalThis.confirmBirdUpgradePreview=confirmBirdUpgradePreview;
