            effectiveDef: curved ? curved.effectiveDef : null,
            curvedBase: curved ? curved.dmg : null,
            enCost: curved ? curved.enCost : null,
            minDamageFloor: curved ? (curved.enCost || 0) * 2 : null,
            isCrit: !!(out && out.isCrit),
